import os
from typing import Any, Dict, Optional

import requests


class ImageSafetyChecker:
    """
    Checks an image for unsafe or policy-sensitive visual content using OpenAI's
    hosted Moderation API.

    Requires:
      - OPENAI_API_KEY environment variable
    """

    def __init__(self, api_key: Optional[str] = None, timeout: int = 30):
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OPENAI_API_KEY is required")
        self.timeout = timeout
        self.url = "https://api.openai.com/v1/moderations"

    def check_image_url(self, image_url: str) -> Dict[str, Any]:
        payload = {
            "model": "omni-moderation-latest",
            "input": [
                {
                    "type": "input_image",
                    "image_url": image_url,
                }
            ],
        }
        return self._post(payload)

    def check_image_bytes(self, image_bytes: bytes, mime_type: str = "image/png") -> Dict[str, Any]:
        import base64

        data_url = f"data:{mime_type};base64,{base64.b64encode(image_bytes).decode('utf-8')}"
        return self.check_image_url(data_url)

    def _post(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        resp = requests.post(self.url, headers=headers, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        data = resp.json()
        return self._normalize_response(data)

    @staticmethod
    def _normalize_response(data: Dict[str, Any]) -> Dict[str, Any]:
        results = data.get("results") or []
        if not results:
            return {
                "flagged": False,
                "categories": {},
                "category_scores": {},
                "raw": data,
            }

        result = results[0]
        categories = result.get("categories", {}) or {}
        scores = result.get("category_scores", {}) or {}
        flagged = bool(result.get("flagged", False))

        return {
            "flagged": flagged,
            "categories": categories,
            "category_scores": scores,
            "raw": data,
        }


def check_image_for_unsafe_content(image_source: str, is_url: bool = True, api_key: Optional[str] = None) -> Dict[str, Any]:
    checker = ImageSafetyChecker(api_key=api_key)
    if is_url:
        return checker.check_image_url(image_source)
    with open(image_source, "rb") as f:
        return checker.check_image_bytes(f.read())
